const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/advanced_forecastings/rows',
  qs: {
    budget_view_id: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    filters: '[object Object]'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/advanced_forecastings/rows?budget_view_id=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters=%5Bobject%20Object%5D"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/advanced_forecastings/rows',
  headers: {'content-type': 'application/json'},
  body: {
    async: false,
    budget_view_id: '42',
    forecasting_rows: [
      {
        budget_line_item_id: '56',
        wbs_code_id: '76',
        start_date: '2024-06-24',
        end_date: '2024-07-24',
        curve: 'manual',
        forecast_to_complete: 100,
        periods: [{period_date: '2024-06', amount: 100, percentage: 25}]
      }
    ]
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v2.0/companies/%7Bcompany_id%7D/projects/%7Bproject_id%7D/advanced_forecastings/rows"),
    Content = new StringContent("{\"async\":false,\"budget_view_id\":\"42\",\"forecasting_rows\":[{\"budget_line_item_id\":\"56\",\"wbs_code_id\":\"76\",\"start_date\":\"2024-06-24\",\"end_date\":\"2024-07-24\",\"curve\":\"manual\",\"forecast_to_complete\":100,\"periods\":[{\"period_date\":\"2024-06\",\"amount\":100,\"percentage\":25}]}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
